  "implementation": "import math

def solve(case):
    # Validate required fields
    required = ['sentence_vectors', 'query_vector', 'context_weight']
    for key in required:
        if key not in case:
            raise ValueError(f"Missing required field: {key}")

    sentence_vectors = case['sentence_vectors']
    query_vector = case['query_vector']
    context_weight = case['context_weight']

    # Compute cosine similarities
    def cosine_sim(v1, v2):
        dot = sum(a * b for a, b in zip(v1, v2))
        norm1 = math.sqrt(sum(a * a for a in v1))
        norm2 = math.sqrt(sum(a * a for a in v2))
        if norm1 == 0.0 or norm2 == 0.0:
            return 0.0
        return dot / (norm1 * norm2)

    sims = [cosine_sim(sv, query_vector) for sv in sentence_vectors]

    # Compute neighbor averages
    n = len(sims)
    neighbor_avgs = []
    for i in range(n):
        neighbor_sims = []
        if i - 1 >= 0:
            neighbor_sims.append(sims[i-1])
        if i + 1 < n:
            neighbor_sims.append(sims[i+1])
        if neighbor_sims:
            neighbor_avgs.append(sum(neighbor_sims) / len(neighbor_sims))
        else:
            # Should not happen with at least one neighbor? but handle single sentence case
            neighbor_avgs.append(0.0)

    # Blend scores
    raw_scores = [(1 - context_weight) * sims[i] + context_weight * neighbor_avgs[i] for i in range(n)]

    # Round to 6 decimal places for determinism
    scores = [round(s, 6) for s in raw_scores]

    # Build ranking: sort by (-score, index), then assign ranks 1-based
    indexed = list(enumerate(scores))
    indexed.sort(key=lambda x: (-x[1], x[0]))
    ranking = [0] * n
    for rank, (idx, _) in enumerate(indexed, start=1):
        ranking[idx] = rank

    return {
        'ranking': ranking,
        'scores': scores
    }
